function weightedGrade(items){
  var s=0, w=0;
  for(var i=0;i<items.length;i++){ s += items[i].score*items[i].weight; w += items[i].weight; }
  return w ? s/w : NaN;
}
function neededScore(weightFinal, currentScore, currentWeight, target){
  var totalW = currentWeight + weightFinal;
  if(!(weightFinal > 0)) return NaN;
  return (target*totalW - currentScore*currentWeight) / weightFinal;
}
var EXPORTS = { weightedGrade:weightedGrade, neededScore:neededScore };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GradeForgePure = EXPORTS; }
